function findDerangement(n) {
  const MOD = 1000000007;
  if (n <= 7) {
    // Try every permutation and count those with no fixed point.
    let count = 0;
    const used = new Array(n + 1).fill(false);
    const place = (position) => {
      if (position > n) { count++; return; }
      for (let value = 1; value <= n; value++) {
        if (!used[value] && value !== position) {
          used[value] = true;
          place(position + 1);
          used[value] = false;
        }
      }
    };
    place(1);
    return count;
  }
  // Inclusion-exclusion: sum over k of (-1)^k * n! / k!.
  let total = 0;
  let product = 1;
  for (let k = n; k >= 0; k--) {
    const term = k % 2 === 0 ? product : MOD - product;
    total = (total + term) % MOD;
    if (k > 0) product = (product * k) % MOD;
  }
  return total;
}

